// План specs/admin-plans.md 4.3 (кейс AP-11). Две роли: admin выдаёт / меняет / отзывает тариф — «בדיקה» видит это без перезагрузки.
// ПИШЕТ данные на проде: только аккаунт «בדיקה» (targetRow падает, если строк не ровно одна); Revoke — ОБЯЗАТЕЛЬНО в finally.
// Карта не добавляется, Stripe не открывается: запросы к checkout/billing.stripe.com и запись в api.stripe.com обрываются, в конце — проверка.
// Тег @writes @data, без @prod-safe. Запуск осознанно и отдельно от @prod-safe этой фичи: npx playwright test --project=tests --grep "#2b3784.*@writes"
// Не сверено с сайтом при записи (правило: сайт не открывать) — подписи по скриншотам .qa/screenshots/r3-*.png (19.10).
import { test, expect } from '../../fixtures';
import { setLanguage, openPlansTab, targetRow, dialogFields, choosePlan, revokeIfAssigned, isoDate, enDate } from './plans-helpers';
import {
  menuLink, expectMenuLoaded, openBilling, anyGrantedBadge, grantedBadge, cellValue,
  openAuditLog, auditRow, blockStripe, paymentMethodState, ADMIN_EMAIL, USER_PLAN_TARGET_EMAIL,
} from './plans-read-helpers';

test.describe.configure({ mode: 'serial' });

// Приложение перечитывает выдачу раз в 60 с (комментарий программиста 29.09; 19.10 — 41–47 с); запас до 90 с.
const PROPAGATION_MS = 90_000;
const UNTIL_DAYS = 7;

test.describe('Admin Panel — Plans: active plan for the user', () => {
  test('Grant Pro Tech, change to Starter Tech and revoke: user sees features without reload, audit log keeps before/after, no card added #2b3784 #b42657 @desktop @writes @data', async ({ asUser }) => {
    test.setTimeout(600_000);
    const stamp = new Date().toISOString().slice(0, 16).replace(/[-:T]/g, '');
    const reason = (step: string) => `QA-AUTO #2b3784 ${step} ${stamp}`;

    const admin = await asUser('admin');
    const user = await asUser('user');
    await setLanguage(admin, 'en');
    await setLanguage(user, 'en');
    const adminStripe = await blockStripe(admin);
    const userStripe = await blockStripe(user);

    // Старт только без выдачи: если осталась от прошлого прогона — снять.
    await revokeIfAssigned(admin, reason('pre-clean'));

    try {
      // 0. Исходное состояние: тариф в Plans и у пользователя (ожидается Techory Lite после истечения 19.10), блок оплаты
      await openPlansTab(admin);
      const baselinePlan = await cellValue(admin, await targetRow(admin), 'Plan');
      await openBilling(user);
      await expect(anyGrantedBadge(user)).toHaveCount(0);
      const paymentBefore = await paymentMethodState(user);
      await user.goto('/dashboard');
      await expectMenuLoaded(user);
      await expect(menuLink(user, 'AI')).toHaveCount(0);

      // 1. Выдача Pro Tech до сегодня + 7
      await openPlansTab(admin);
      let row = await targetRow(admin);
      await row.getByRole('button', { name: 'Assign plan', exact: true }).click();
      let f = dialogFields(admin);
      await expect(f.dialog).toBeVisible();
      await choosePlan(admin, f.plan, 'Pro Tech');
      await f.until.fill(isoDate(UNTIL_DAYS));
      await f.reason.fill(reason('grant'));
      await f.save.click();
      await expect(f.dialog).toBeHidden();
      row = await targetRow(admin);
      await expect(row).toContainText('Pro Tech');
      await expect(row).toContainText('Assigned');
      await expect(row).toContainText(reason('grant'));
      await expect(row).toContainText(enDate(UNTIL_DAYS));

      // 2. Пользователь без перезагрузки: появились AI и Inventory (≤60 с)
      await expect(menuLink(user, 'AI')).toBeVisible({ timeout: PROPAGATION_MS });
      await expect(menuLink(user, 'Inventory')).toBeVisible();
      await openBilling(user);
      await expect(user.getByText('Pro Tech', { exact: true }).first()).toBeVisible();
      await expect(user.getByText(grantedBadge(enDate(UNTIL_DAYS)), { exact: true })).toBeVisible();

      // 3. Change / extend → Starter Tech
      await openPlansTab(admin);
      row = await targetRow(admin);
      await row.getByRole('button', { name: 'Change / extend', exact: true }).click();
      f = dialogFields(admin);
      await expect(f.dialog).toBeVisible();
      await choosePlan(admin, f.plan, 'Starter Tech');
      await f.until.fill(isoDate(UNTIL_DAYS));
      await f.reason.fill(reason('change'));
      await f.save.click();
      await expect(f.dialog).toBeHidden();
      row = await targetRow(admin);
      await expect(row).toContainText('Starter Tech');
      await expect(row).toContainText('Assigned');

      // 4. Пользователь без перезагрузки (остаётся на Billing, меню сбоку): AI пропал, Inventory остался
      await expect(menuLink(user, 'AI')).toHaveCount(0, { timeout: PROPAGATION_MS });
      await expect(menuLink(user, 'Inventory')).toBeVisible();
      await openBilling(user);
      await expect(user.getByText('Starter Tech', { exact: true }).first()).toBeVisible();
      await expect(user.getByText(grantedBadge(enDate(UNTIL_DAYS)), { exact: true })).toBeVisible();

      // 5. Revoke: без причины кнопка неактивна; с причиной — пользователь на своём тарифе
      await user.goto('/dashboard');
      await expectMenuLoaded(user);
      await expect(menuLink(user, 'Inventory')).toBeVisible();
      await openPlansTab(admin);
      row = await targetRow(admin);
      await row.getByRole('button', { name: 'Revoke', exact: true }).click();
      f = dialogFields(admin);
      await expect(f.dialog).toBeVisible();
      await f.reason.fill('');
      await expect(f.revoke).toBeDisabled();
      await f.reason.fill(reason('revoke'));
      await f.revoke.click();
      await expect(f.dialog).toBeHidden();
      row = await targetRow(admin);
      await expect(row.getByRole('button', { name: 'Assign plan', exact: true })).toBeVisible();
      await expect(row).not.toContainText('Assigned');
      expect(await cellValue(admin, row, 'Plan')).toBe(baselinePlan);

      // 6. Пользователь без перезагрузки: Inventory и AI пропали; Billing — исходный тариф без бейджа
      await expect(menuLink(user, 'Inventory')).toHaveCount(0, { timeout: PROPAGATION_MS });
      await expect(menuLink(user, 'AI')).toHaveCount(0);
      await openBilling(user);
      await expect(user.getByText(baselinePlan, { exact: true }).first()).toBeVisible();
      await expect(anyGrantedBadge(user)).toHaveCount(0);

      // 7. Карта не появилась
      expect(await paymentMethodState(user), 'блок Payment method как до выдачи').toEqual(paymentBefore);

      // 8. Audit log: три записи с Who / Account, в деталях — Before / After и причина (S-15 AC 6)
      await openAuditLog(admin);
      for (const [action, step] of [['Plan granted', 'grant'], ['Plan changed', 'change'], ['Plan revoked', 'revoke']] as const) {
        const entry = auditRow(admin, action, USER_PLAN_TARGET_EMAIL);
        await expect(entry, `запись «${action}»`).toBeVisible({ timeout: 30_000 });
        await expect(entry).toContainText(ADMIN_EMAIL);
        await entry.click();
        await expect(admin.getByText(reason(step), { exact: true }).first(), `причина в «${action}»`).toBeVisible();
        await expect(admin.getByText('Before', { exact: true }).first()).toBeVisible();
        await expect(admin.getByText('After', { exact: true }).first()).toBeVisible();
        await entry.click(); // свернуть
      }
      const granted = auditRow(admin, 'Plan granted', USER_PLAN_TARGET_EMAIL);
      await expect(granted).toContainText(/pro_tech|Pro Tech/);
      const changed = auditRow(admin, 'Plan changed', USER_PLAN_TARGET_EMAIL);
      await expect(changed).toContainText(/pro_tech|Pro Tech/);
      await expect(changed).toContainText(/starter_tech|Starter Tech/);
    } finally {
      // Очистка всегда, даже при падении проверки.
      await revokeIfAssigned(admin, reason('cleanup'));
    }

    expect([...adminStripe, ...userStripe], 'Stripe не должен открываться, карта не добавляется').toEqual([]);
  });
});
